  project.template.aiDesignDraft.objectStyleApplication=window.ACDLDesignObjectStylePresets.apply(project,designSpec);
  await updateTemplateEditorBuildProgress(70,"편집 개체 변환","텍스트·월력·메모·이미지를 개별 편집 가능한 개체로 구성했습니다.");
